(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-640":{scenario:{company:"Sông Mây Bridge & Road Consultants",supervisor:{name:"Lâm Gia Hưng",role:{vi:"Chủ trì thiết kế cầu",en:"Lead Bridge Engineer"}},ref_code:"BRG-0905",title:{vi:"Biết gối cố định ở đâu, tính chuyển vị từ đó.",en:"Know the fixed bearing, measure movement from it."},brief:{vi:"Bạn soát xét hồ sơ khe co giãn BRG-0905 tại mố M2 của cầu dầm liên tục bê tông dự ứng lực dài 90 m. Gối cố định đặt tại mố M1; các trụ và mố M2 dùng gối di động dọc. Biên độ nhiệt kết cấu thiết kế 50 °C, α = 10,8 x 10^-6 /°C; co ngót, từ biến quy đổi 0,0002 x chiều dài giãn nở (mô phỏng). Hãy sửa loại khe co giãn và tổng chuyển vị thiết kế tại khe M2 (mm), rồi lập báo cáo có căn cứ.",en:"You are reviewing expansion joint file BRG-0905 at abutment M2 of a 90 m continuous prestressed concrete girder bridge. The fixed bearing is at abutment M1; the piers and M2 have longitudinally movable bearings. The design structural temperature range is 50 °C, α = 10.8 x 10^-6 /°C; shrinkage and creep equal 0.0002 x expansion length (simulated). Correct the joint type and the total design movement at joint M2 (mm), then write an evidence-based report."},reference_title:{vi:"Sơ đồ gối cầu & bảng chọn khe co giãn đã duyệt",en:"Approved bearing layout & joint selection table"},fields:[{id:"JOINT_TYPE",label:{vi:"Loại khe co giãn tại mố M2",en:"Expansion joint type at abutment M2"},initial:"ASPHALTIC-PLUG",expected:"STRIP-SEAL",choices:["ASPHALTIC-PLUG","STRIP-SEAL","MODULAR"],reference:"Bảng chọn khe co giãn của dự án",ref_value:{vi:"Theo tổng chuyển vị (mô phỏng): đến 40 mm khe bitum; 40-100 mm khe dải cao su; trên 100 mm khe module",en:"By total movement (simulated): up to 40 mm asphaltic plug; 40-100 mm strip seal; over 100 mm modular"},hint:{vi:"Loại khe chỉ chọn được sau khi có tổng chuyển vị đúng; bản nháp chọn theo một chuyển vị đã tính sai.",en:"The joint type follows from the correct total movement; the draft chose it from a wrong value."}},{id:"MOVE_MM",label:{vi:"Tổng chuyển vị thiết kế tại khe M2 (mm)",en:"Total design movement at joint M2 (mm)"},initial:"33.3",expected:"66.6",reference:"Bảng tính chuyển vị khe co giãn",ref_value:{vi:"Chiều dài cầu 90 m; gối cố định tại M1; ΔT 50 °C; α 10,8 x 10^-6 /°C; co ngót, từ biến 0,0002 L",en:"Bridge length 90 m; fixed bearing at M1; ΔT 50 °C; α 10.8 x 10^-6 /°C; shrinkage, creep 0.0002 L"},hint:{vi:"Bản nháp lấy chiều dài giãn nở bằng nửa cầu, như thể gối cố định nằm ở giữa cầu.",en:"The draft took half the bridge as the expansion length, as if the fixed bearing were at midspan."}}],sop32:{vi:"Chiều dài giãn nở L = khoảng cách từ gối cố định đến khe. Chuyển vị nhiệt = α x L x ΔT; co ngót, từ biến = 0,0002 x L; tổng chuyển vị = nhiệt + co ngót, từ biến, ghi đến 0,1 mm.",en:"Expansion length L = distance from the fixed bearing to the joint. Thermal movement = α x L x ΔT; shrinkage and creep = 0.0002 x L; total movement = thermal + shrinkage and creep, stated to 0.1 mm."},context:{label:"BRIDGE-CAD / BRG-0905",metrics:[{label:{vi:"Chiều dài liên tục",en:"Continuous length"},value:"90 m"},{label:{vi:"Biên độ nhiệt kết cấu",en:"Structural temperature range"},value:"50 °C"},{label:{vi:"Vị trí gối cố định",en:"Fixed bearing location"},value:"M1"}]},terminal:{system:"bridge-design",settable:["JOINT_TYPE","MOVE_MM"],commands:[{cmd:"status",out:{vi:"Hồ sơ BRG-0905 (nháp): khe M2 = ASPHALTIC-PLUG; tổng chuyển vị 33,3 mm; đã gửi nhà thầu đặt hàng",en:"File BRG-0905 (draft): joint M2 = ASPHALTIC-PLUG; total movement 33.3 mm; sent to the contractor for ordering"}},{cmd:"cat bearing-layout.txt",out:{vi:"M1: gối cố định; T1, T2: gối di động dọc; M2: gối di động dọc. Chiều dài liên tục 90 m",en:"M1: fixed bearing; P1, P2: longitudinally movable; M2: longitudinally movable. Continuous length 90 m"}},{cmd:"cat climate.txt",out:{vi:"Nhiệt độ kết cấu thiết kế (mô phỏng): lớn nhất 55 °C, nhỏ nhất 5 °C",en:"Design structural temperature (simulated): maximum 55 °C, minimum 5 °C"}},{cmd:"cat material.txt",out:{vi:"Bê tông thường: α = 10,8 x 10^-6 /°C; co ngót, từ biến quy đổi 0,0002 x L",en:"Normal-weight concrete: α = 10.8 x 10^-6 /°C; equivalent shrinkage and creep 0.0002 x L"}},{cmd:"calc movement --draft",out:{vi:"Bản nháp: L = 45 m (giả định gối cố định ở giữa cầu), chuyển vị 24,3 + 9,0 = 33,3 mm",en:"Draft: L = 45 m (fixed bearing assumed at midspan), movement 24.3 + 9.0 = 33.3 mm"}}]},crisis:{vi:"Nhà thầu: “Khe bitum đã đặt hàng, đổi loại là trễ lễ thông xe. Anh ký duyệt shop drawing giữ khe bitum đi, hỏng thì kỳ bảo trì thay.” Trưởng ban quản lý dự án cũng muốn ký cho kịp ngày khánh thành.",en:"The contractor: “The asphaltic plug joints are already ordered; changing type delays the opening. Approve the shop drawing with the plug joint and maintenance can replace it later.” The PMU head also wants it signed for the ceremony."},options:{safe:{vi:"Không duyệt khe sai loại; báo chủ trì thiết kế và ban quản lý dự án bằng văn bản, đề xuất đặt gấp khe dải cao su đúng chuyển vị hoặc phương án tạm được thiết kế phê duyệt và kiểm tra trước thông xe.",en:"Do not approve the wrong joint; notify the design lead and PMU in writing and propose expedited supply of a strip seal sized for the movement or a designer-approved interim solution checked before opening."},shortcut:{vi:"Ký duyệt khe bitum cho kịp lễ thông xe, ghi chú thay thế trong kỳ bảo trì.",en:"Approve the plug joint to make the opening and note a replacement in the maintenance cycle."},wait:{vi:"Không ký nhưng cũng không phản hồi, để nhà thầu tự lắp theo vật tư đã đặt.",en:"Do not sign or reply, leaving the contractor to install what was ordered."}},questions:{vi:["Giải thích cách bạn xác định chiều dài giãn nở từ sơ đồ gối và tính tổng chuyển vị tại khe M2.","Lắp khe co giãn không đủ khả năng chuyển vị gây hư hỏng và rủi ro an toàn giao thông nào? Bạn xử lý áp lực tiến độ ra sao?"],en:["Explain how you derived the expansion length from the bearing layout and computed the total movement at joint M2.","What damage and traffic safety risks follow from installing a joint with insufficient movement capacity? How do you handle the schedule pressure?"]},hints:{vi:["Mở sơ đồ bố trí gối và xác định vị trí gối cố định trước khi đo chiều dài giãn nở.","Theo SOP mục 3.2, cộng chuyển vị nhiệt với co ngót, từ biến trên đúng chiều dài từ gối cố định đến khe.","SOP mục 4.2: không phê duyệt thiết bị thiếu khả năng chỉ vì vật tư đã đặt; báo chủ trì và ban quản lý dự án."],en:["Open the bearing layout and locate the fixed bearing before measuring the expansion length.","Under SOP 3.2, add thermal movement to shrinkage and creep over the true length from the fixed bearing to the joint.","SOP 4.2: never approve inadequate equipment because it is already ordered; escalate to the design lead and PMU."]}},learning:{summary:{vi:"Kỹ sư hạ tầng giao thông và cầu đường thiết kế, kiểm định và giám sát đường ô tô, nút giao, cống, cầu dầm và cầu dây, bảo đảm công trình chịu được hoạt tải xe, tác động môi trường và khai thác an toàn trong nhiều thập kỷ. Họ phối hợp khảo sát, thủy văn, địa kỹ thuật và thi công để chọn giải pháp tối ưu chi phí vòng đời. Nghề đòi hỏi cơ học kết cấu vững, hiểu tiêu chuẩn thiết kế cầu đường và trách nhiệm với an toàn giao thông.",en:"A civil infrastructure and bridge engineer designs, inspects and supervises roads, interchanges, culverts, girder and cable bridges, ensuring they carry vehicle loads, resist environmental actions and serve safely for decades. They combine survey, hydrology, geotechnics and construction input to choose the best life-cycle solution. The role needs strong structural mechanics, command of bridge and road design codes and responsibility for traffic safety."},responsibilities:{vi:["Thiết kế bình đồ, trắc dọc, trắc ngang, kết cấu áo đường và hệ thống thoát nước.","Thiết kế kết cấu nhịp, mố trụ, gối cầu, khe co giãn theo tiêu chuẩn thiết kế cầu.","Tính hoạt tải, tác động nhiệt, co ngót, từ biến, động đất và kiểm toán các trạng thái giới hạn.","Duyệt bản vẽ thi công, biện pháp lao lắp dầm và giám sát tác giả tại công trường.","Kiểm định, thử tải và lập kế hoạch bảo trì cầu đường đang khai thác."],en:["Design horizontal and vertical alignment, cross sections, pavement and drainage.","Design superstructure, piers and abutments, bearings and expansion joints to bridge codes.","Compute live load, thermal, shrinkage, creep and seismic effects and check limit states.","Review shop drawings and girder erection methods and provide designer supervision on site.","Inspect and load test bridges and roads in service and plan their maintenance."]},competencies:[{name:{vi:"Thiết kế cầu",en:"Bridge design"},desc:{vi:"Chọn sơ đồ kết cấu, bố trí gối, khe và kiểm toán theo tiêu chuẩn thiết kế cầu đường bộ.",en:"Choose structural systems, arrange bearings and joints and check them to highway bridge codes."}},{name:{vi:"Thiết kế đường",en:"Road design"},desc:{vi:"Thiết kế hình học, kết cấu áo đường, nút giao và tổ chức an toàn giao thông.",en:"Design geometry, pavement structure, interchanges and traffic safety features."}},{name:{vi:"Phân tích kết cấu",en:"Structural analysis"},desc:{vi:"Mô hình hóa cầu, xếp tải bất lợi và phân tích theo các giai đoạn thi công.",en:"Model bridges, place loads in the worst positions and analyse construction stages."}},{name:{vi:"Phối hợp liên ngành",en:"Interdisciplinary coordination"},desc:{vi:"Kết hợp số liệu thủy văn, địa chất, giao thông và biện pháp thi công.",en:"Integrate hydrology, geology, traffic data and construction methods."}},{name:{vi:"Trách nhiệm an toàn công cộng",en:"Public safety accountability"},desc:{vi:"Không phê duyệt giải pháp thiếu an toàn dưới áp lực tiến độ hay ngày khánh thành.",en:"Never approve unsafe solutions under schedule or ceremony pressure."}}],knowledge:{vi:["TCVN 11823:2017 - Thiết kế cầu đường bộ (bộ tiêu chuẩn gồm nhiều phần).","TCVN 4054:2005 - Đường ô tô: yêu cầu thiết kế.","Mô hình hoạt tải HL-93 (xe tải, xe hai trục và tải trọng làn) theo phương pháp hệ số tải trọng và sức kháng.","Nguyên lý bố trí gối cố định, gối di động và tính chuyển vị nhiệt, co ngót, từ biến của kết cấu nhịp.","Quy định hiện hành về quản lý, bảo trì và kiểm định công trình giao thông đường bộ."],en:["TCVN 11823:2017 - Highway bridge design (a multi-part standard).","TCVN 4054:2005 - Highways: design requirements.","HL-93 live load model (design truck, tandem and lane load) under load and resistance factor design.","Principles of fixed and movable bearing layout and thermal, shrinkage and creep movement of the deck.","Current rules on management, maintenance and inspection of road infrastructure."]},tools:["Phần mềm phân tích kết cấu cầu","Phần mềm thiết kế đường và mô hình địa hình","Phần mềm CAD và BIM hạ tầng","Máy toàn đạc, máy thủy bình","Thiết bị đo võng, ứng suất khi thử tải"],kpis:{vi:["Số lỗi thiết kế phát hiện sau phát hành (mục tiêu bằng 0).","Chênh lệch độ võng thử tải thực đo so với tính toán.","Tỷ lệ hồ sơ qua thẩm tra không phải sửa lớn.","Chi phí vòng đời (xây dựng và bảo trì) so với phương án so sánh."],en:["Design errors found after issue (target zero).","Difference between measured and predicted load test deflection.","Share of designs passing review without major changes.","Life-cycle cost (construction and maintenance) against the alternative scheme."]},day:[{time:"08:00",vi:"Rà soát yêu cầu làm rõ kỹ thuật của nhà thầu về gối cầu và khe co giãn.",en:"Review contractor RFIs on bearings and expansion joints."},{time:"09:30",vi:"Chạy mô hình kết cấu nhịp với hoạt tải, nhiệt độ và các giai đoạn thi công.",en:"Run the deck model with live load, temperature and construction stages."},{time:"13:30",vi:"Duyệt shop drawing mố trụ, gối và khe; đối chiếu với chuyển vị thiết kế.",en:"Review shop drawings for substructure, bearings and joints against design movements."},{time:"15:30",vi:"Họp với ban quản lý dự án về tiến độ lao dầm và kế hoạch thử tải.",en:"Meet the PMU on girder erection progress and the load test plan."},{time:"17:00",vi:"Cập nhật thuyết minh, ghi nhật ký thay đổi và lưu hồ sơ.",en:"Update the design report, log changes and archive the file."}],mistakes:{vi:["Tính chuyển vị từ giữa cầu trong khi gối cố định đặt ở một đầu.","Bỏ qua co ngót, từ biến khi chọn khe co giãn cho cầu bê tông dự ứng lực.","Phê duyệt vật tư theo đơn hàng sẵn có thay vì theo yêu cầu thiết kế."],en:["Computing movement from midspan when the fixed bearing is at one end.","Ignoring shrinkage and creep when sizing joints for prestressed concrete bridges.","Approving materials because they were ordered rather than because they meet the design."]},career:[{vi:"Kỹ sư cầu đường tập sự",en:"Graduate bridge and road engineer"},{vi:"Kỹ sư thiết kế cầu đường",en:"Bridge and road design engineer"},{vi:"Chủ trì thiết kế cầu",en:"Lead bridge engineer"},{vi:"Giám đốc kỹ thuật hạ tầng giao thông",en:"Transport infrastructure technical director"}],glossary:[{term:"Expansion joint",vi:"Khe co giãn cho phép kết cấu nhịp dịch chuyển do nhiệt, co ngót, từ biến mà mặt cầu vẫn liên tục.",en:"Joint letting the deck move under temperature, shrinkage and creep while keeping the riding surface continuous."},{term:"Fixed bearing",vi:"Gối không cho chuyển vị ngang, là điểm gốc để tính chiều dài giãn nở.",en:"Bearing restraining horizontal movement, the origin for measuring expansion length."},{term:"HL-93",vi:"Mô hình hoạt tải xe thiết kế gồm xe tải hoặc xe hai trục kết hợp với tải trọng làn.",en:"Design vehicular live load model: truck or tandem combined with a lane load."},{term:"Creep",vi:"Biến dạng của bê tông tăng dần theo thời gian dưới tải trọng duy trì.",en:"Gradual increase of concrete strain over time under sustained load."},{term:"Load test",vi:"Thử tải cầu bằng xe có tải trọng biết trước để đo võng, ứng suất và đánh giá khả năng khai thác.",en:"Loading a bridge with known vehicles to measure deflection and stress and assess serviceability."}],quiz:[{q:{vi:"Cầu dài 60 m, gối cố định ở một mố, α = 10 x 10^-6 /°C, ΔT = 40 °C. Chuyển vị nhiệt tại khe ở đầu kia là bao nhiêu?",en:"A 60 m bridge has its fixed bearing at one abutment, α = 10 x 10^-6 /°C, ΔT = 40 °C. What is the thermal movement at the far joint?"},options:{vi:["12 mm","48 mm","2,4 mm","24 mm"],en:["12 mm","48 mm","2.4 mm","24 mm"]},answer:3,explain:{vi:"Chuyển vị = 10 x 10^-6 x 60 000 mm x 40 = 24 mm, tính trên toàn bộ 60 m từ gối cố định.",en:"Movement = 10 x 10^-6 x 60,000 mm x 40 = 24 mm, over the full 60 m from the fixed bearing."}},{q:{vi:"Tiêu chuẩn quốc gia nào dùng cho thiết kế cầu đường bộ ở Việt Nam?",en:"Which national standard governs highway bridge design in Vietnam?"},options:{vi:["TCVN 4453:1995","TCVN 11823:2017","TCVN 5574:2018","TCVN 9386:2012"],en:["TCVN 4453:1995","TCVN 11823:2017","TCVN 5574:2018","TCVN 9386:2012"]},answer:1,explain:{vi:"TCVN 11823:2017 là bộ tiêu chuẩn thiết kế cầu đường bộ theo hệ số tải trọng và sức kháng.",en:"TCVN 11823:2017 is the highway bridge design standard based on load and resistance factors."}},{q:{vi:"Nhà thầu đề nghị giữ khe co giãn không đủ khả năng chuyển vị để kịp thông xe. Bạn làm gì?",en:"The contractor proposes keeping a joint with insufficient movement capacity to open on time. What do you do?"},options:{vi:["Không phê duyệt, báo chủ trì, ban quản lý và đề xuất đặt gấp khe đúng loại hoặc phương án tạm được duyệt","Ký duyệt rồi thay sau","Cho lắp tạm mà không báo cáo","Để nhà thầu tự quyết định"],en:["Refuse, inform the lead and PMU and propose expedited correct joints or an approved interim fix","Approve now and replace later","Allow a temporary install without reporting","Let the contractor decide"]},answer:0,explain:{vi:"Khe thiếu khả năng chuyển vị có thể bị phá hỏng, gây nguy hiểm cho xe cộ; an toàn công cộng phải đặt trên ngày khánh thành.",en:"An undersized joint can fail and endanger traffic; public safety comes before the opening date."}},{q:{vi:"Vì sao cầu bê tông dự ứng lực cần cộng co ngót, từ biến vào chuyển vị khe?",en:"Why must prestressed concrete bridges add shrinkage and creep to joint movement?"},options:{vi:["Vì làm tăng nhiệt độ kết cấu","Vì làm tăng hoạt tải xe","Vì gây co ngắn dài hạn của kết cấu nhịp","Vì làm gối cố định dịch chuyển"],en:["They raise the structural temperature","They increase vehicle loads","They cause long-term shortening of the deck","They move the fixed bearing"]},answer:2,explain:{vi:"Co ngót và từ biến dưới lực nén trước làm kết cấu nhịp ngắn dần, mở rộng khe theo thời gian.",en:"Shrinkage and creep under prestress shorten the deck over time, opening the joint."}}],tools_en:["Bridge structural analysis software","Road design and terrain modeling software","Infrastructure CAD and BIM software","Total station and leveling instrument","Deflection and strain gauges for load tests"]}}})})(window.KKR);
